using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class TreasureTrailChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var old=new SliceState();string before=JsonUtility.ToJson(old);for(int i=0;i<7;i++)TreasureTrailText.Read(old,i);Require(before==JsonUtility.ToJson(old)&&old.treasureTrail==null,"Read invented player history");var m=new TreasureTrailState();Require(!m.Share(0,true)&&!m.Find(-1)&&!m.Find(6),"Unfound / invalid discovery shared");Require(m.Find(0)&&!m.Find(0)&&m.Share(0,true)&&!m.Share(0,false)&&m.Valid(),"Once-only discovery/offer invalid");var s=new SliceState{treasureTrail=m};Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(s)).Valid()&&TreasureTrailText.Read(s,1).text.Contains("strawberry"),"Shared food note/save invalid");for(int i=1;i<6;i++){m.Find(i);m.Share(i,false);}Require(TreasureTrailState.Count(m.found)==6&&TreasureTrailState.Count(m.shared)==6&&m.Valid(),"Full trail invalid");m.shared=64;Require(!m.Valid(),"Oversized mask accepted");m.shared=0;Require(!m.Valid(),"Food not shared accepted");m.food=0;m.found=0;m.shared=1;Require(!m.Valid(),"Invented player discovery accepted");Debug.Log("BWVR_TREASURE_MODEL_PASS: unknown history, pure Book, six bounded sites, source distinction, one-shot sharing and save/corruption checks");}
 public static void Verify(){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var field=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)field.GetValue(slice);var world=slice.GetComponentInChildren<IslandDiscoveries>();var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=god.GetComponent<IslandNavigator>();var mind=god.GetComponent<CreatureCuriosity>();Require(!nav.world.TreeNavigationPending,"Wait for navigation");var gp=god.transform.position;var gr=god.transform.rotation;var people=slice.GetComponentsInChildren<VillagerSocial>();var positions=people.Select(p=>p.transform.position).ToArray();var objects=world.points.SelectMany(p=>p.objects).ToArray();var objectPositions=objects.Select(o=>o.transform.position).ToArray();var rotations=objects.Select(o=>o.transform.rotation).ToArray();var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);var held=(CarryItem[])typeof(QuestSlice).GetField("held",Flags).GetValue(slice);Require(held.All(i=>i==null),"Release player objects");var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,hunger=.8f,playPreference=1};var ideas=slice.GetComponentsInChildren<ConstructionInspiration>();var ideaActive=ideas.Select(i=>i.gameObject.activeSelf).ToArray();
  CarryItem[] Offers()=>(CarryItem[])typeof(QuestSlice).GetField("treasureOffers",Flags).GetValue(slice);
  CarryItem Pending()=>Offers().FirstOrDefault(i=>i!=null);
  bool Grab(CarryItem item)=>(bool)typeof(QuestSlice).GetMethod("TryGrab",Flags).Invoke(slice,new object[]{1,item});
  void Drop(Vector3 at)=>typeof(QuestSlice).GetMethod("Release",Flags).Invoke(slice,new object[]{1,new Ray(at+Vector3.up*nav.world.Scale*30,Vector3.down)});
  void Completed(CreatureAffordance a)=>typeof(QuestSlice).GetMethod("TreasureCompleted",Flags).Invoke(slice,new object[]{a});
  void SilenceOthers(CreatureAffordance keep){foreach(var a in cooldowns.Keys)a.cooldown=a==keep?0:test.Hybrid.time+200;}
  void Accept(DiscoveryObject find){var item=find.GetComponent<CarryItem>();var affordance=find.GetComponent<CreatureAffordance>();SilenceOthers(affordance);bool active=false;for(int i=0;i<900&&!test.treasureTrail.Shared(find.point.id);i++){god.Tick(.05f);active|=god.Owner==CreatureHybrid.ActionOwner.Curiosity;typeof(QuestSlice).GetMethod("AdvanceTreasureTrail",Flags).Invoke(slice,new object[]{false});}Require(active&&test.treasureTrail.Shared(find.point.id)&&!item.held,"Creature did not autonomously complete offered discovery: "+god.Explanation+" / "+mind.Current);}
  try{
   god.Interrupt("Treasure QA");foreach(var p in people){p.ResetTask();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerBlockPlay>().ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.transform.position+=Vector3.up*nav.world.Scale*500;}foreach(var idea in ideas)idea.gameObject.SetActive(false);field.SetValue(slice,test);god.NewSeason();world.ResetWorld();slice.SetSanctuaryOpen(false);var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);
   var lane=slice.GetComponentInChildren<BeachBall>().Bowling;Require(nav.world.Sample(lane.Start-lane.Right*12*nav.world.Scale,nav.profile,8,out var stage),"No creature staging point");god.transform.position=nav.world.ProjectFoot(stage,nav.profile);god.transform.rotation=Quaternion.LookRotation(lane.Forward);nav.ResetRoute();var food=objects.First(o=>o.treat);var item=food.GetComponent<CarryItem>();test.paused=true;Require(Grab(item),"Paused native pickup failed");Drop(item.home);Require(test.treasureTrail==null||test.treasureTrail.found==0,"Paused pickup recorded a find");test.paused=false;
   Require(Grab(item)&&test.treasureTrail.Found(food.point.id)&&test.treasureTrail.shared==0,"Home pickup did not record player find");Drop(item.home);Require(Pending()==null,"Distant drop offered a gift");Require(Grab(item),"Cannot re-present discovery");var gift=god.transform.position+god.transform.forward*nav.world.Scale*5;Drop(gift);Require(Pending()==item&&test.treasureTrail.shared==0,"Drop credited before acceptance");Completed(objects.First(o=>o!=food).GetComponent<CreatureAffordance>());Require(test.treasureTrail.shared==0,"Unrelated completion accepted gift");Require(Grab(item)&&Pending()==null,"Taking gift back did not cancel offer");Completed(food.GetComponent<CreatureAffordance>());Require(test.treasureTrail.shared==0,"Player-held gift accepted");Drop(gift);Require(mind.TryBegin(food.GetComponent<CreatureAffordance>()),"Cannot stage interruption");god.Interrupt("Interrupted gift QA");Require(test.treasureTrail.shared==0,"Interrupted interaction accepted gift");Accept(food);Require((test.treasureTrail.food&(1<<food.point.id))!=0&&Pending()==null,"Eating lost food attribution / retained offer");int shared=test.treasureTrail.shared;Completed(food.GetComponent<CreatureAffordance>());Require(test.treasureTrail.shared==shared,"Repeated completion farmed discovery");
   var tool=objects.First(o=>!o.treat&&o.point.id!=food.point.id);var toolItem=tool.GetComponent<CarryItem>();Require(Grab(toolItem),"Tool home pickup failed");Drop(gift);Require(Pending()==toolItem,"Tool not offered");var second=objects.First(o=>!o.treat&&o.point.id!=food.point.id&&o.point.id!=tool.point.id).GetComponent<CarryItem>();Require(Grab(second),"Second find pickup failed");Drop(gift+god.transform.right*nav.world.Scale*3);Require(Offers().Contains(toolItem)&&Offers().Contains(second),"Second offer erased the first");typeof(QuestSlice).GetMethod("Save",Flags).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",Flags).Invoke(slice,null);test=(SliceState)field.GetValue(slice);Completed(tool.GetComponent<CreatureAffordance>());Require(test.treasureTrail.shared==shared,"Reload credited stale offer");typeof(QuestSlice).GetMethod("AdvanceTreasureTrail",Flags).Invoke(slice,new object[]{false});Require(Pending()==null&&test.treasureTrail.Found(tool.point.id)&&test.Valid(),"Native save lost found history or retained pending ownership");Require(Grab(toolItem),"Saved find cannot be offered again");Drop(gift);test.Hybrid.time+=61;typeof(QuestSlice).GetMethod("AdvanceTreasureTrail",Flags).Invoke(slice,new object[]{false});Completed(tool.GetComponent<CreatureAffordance>());Require(Pending()==null&&!test.treasureTrail.Shared(tool.point.id),"Expired gift credited");Require(Grab(toolItem),"Expired find cannot be re-presented");Drop(gift);Accept(tool);Require((test.treasureTrail.food&(1<<tool.point.id))==0&&TreasureTrailText.Read(test,tool.point.id+1).text.Contains("FIELD NOTE"),"Tool note confused with food");
   Require(slice.MarkFindPage(0)&&!slice.MenuOpen,"Optional Find beacon failed");Debug.Log("BWVR_TREASURE_RUNTIME_PASS: native home pickup, pause, distance, hand ownership/re-present, unrelated/duplicate/reload/expiry guards, utility-selected food and toy acceptance, native save/load and optional marker");
  }finally{if(held[1]!=null){held[1].held=false;held[1].GetComponent<Collider>().enabled=true;held[1]=null;}god.Interrupt("Treasure QA ended");field.SetValue(slice,original);world.ResetWorld();god.NewSeason();for(int i=0;i<people.Length;i++){people[i].transform.position=positions[i];people[i].GetComponent<IslandNavigator>().ResetRoute();}for(int i=0;i<objects.Length;i++)objects[i].transform.SetPositionAndRotation(objectPositions[i],rotations[i]);for(int i=0;i<ideas.Length;i++)ideas[i].gameObject.SetActive(ideaActive[i]);foreach(var pair in cooldowns)pair.Key.cooldown=pair.Value;god.transform.SetPositionAndRotation(gp,gr);nav.ResetRoute();typeof(QuestSlice).GetMethod("ClearTreasureOffer",Flags).Invoke(slice,null);typeof(QuestSlice).GetMethod("ClearOutingMark",Flags).Invoke(slice,null);slice.SetSanctuaryOpen(false);}
 }
}
}
